def get_user_or_create(strategy, details, user=None, *args, **kwargs):
    """Return a User with the given username iff the User exists,
    or create a new User iff the User doesn't exist.
    """
    if user and user.is_active:
        return user
    username = kwargs.get('username')
    if username is None:
        username = details.get('username')
    if username is None:
        username = details.get('email')
    if username is None:
        username = details.get('id')
    try:
        user = User.objects.get(username=username)
    except User.DoesNotExist:
        user = User(username=username)
    return user


